def solve(s):
    # split into four parts
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # each part must be non-empty and digits only
        if not part:
            return False
        if not part.isdigit():
            return False
        # no leading zeros unless the part is exactly '0'
        if len(part) > 1 and part[0] == '0':
            return False
        # numeric range 0-255
        try:
            val = int(part)
        except ValueError:
            return False
        if not (0 <= val <= 255):
            return False
    return True

