def solve(matrix):
    """Return determinant of integer matrix using Bareiss algorithm.
    Empty matrix => 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # make copy
    a = [row[:] for row in matrix]
    det_sign = 1
    for k in range(n-1):
        # pivot selection
        if a[k][k] == 0:
            # find non-zero pivot below
            swap_row = None
            for i in range(k+1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            a[k], a[swap_row] = a[swap_row], a[k]
            det_sign = -det_sign
        pivot = a[k][k]
        prev_pivot = a[k-1][k-1] if k > 0 else 1
        for i in range(k+1, n):
            for j in range(k+1, n):
                a[i][j] = (a[i][j]*pivot - a[i][k]*a[k][j]) // prev_pivot
            a[i][k] = 0
    return det_sign * a[n-1][n-1]

