def solve(nums):
    """Return length of longest strictly increasing subsequence.
    O(n log n) using patience sorting.
    """
    if not nums:
        return 0
    import bisect
    tails = []
    for x in nums:
        # find first tail >= x
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

