def solve(path: str) -> str:
    """Simplify an absolute Unix file path.
    - Resolves '.' and '..'
    - Collapses multiple slashes
    - Removes any trailing slash (except for root)
    Returns '/' for the root directory. If the input is an empty string, returns an empty string.
    """
    if not path:
        return ''
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

