def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting algorithm with O(n log n) time.
    """
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # find position to replace: first element >= x
        pos = bisect.bisect_left(tails, x)
        if pos == len(tails):
            tails.append(x)
        else:
            tails[pos] = x
    return len(tails)

