def solve(s):
    """Return True if brackets in s are balanced.
    Non-string inputs (including None) return False.
    Bytes are decoded as UTF-8; decoding failures return False.
    """
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode('utf-8')
        except Exception:
            return False
    if not isinstance(s, str):
        return False
    stack = []
    closing_map = {')': '(', ']': '[', '}': '{'}
    opening = set(closing_map.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in closing_map:
            if not stack or stack[-1] != closing_map[ch]:
                return False
            stack.pop()
        else:
            continue
    return not stack

